function sqlEscape(str: any): string {
  if (str === null || str === undefined) return "''";
  return "'" + String(str).replace(/'/g, "''") + "'";
}

export async function populateRealInventory(db: PGlite, force = false): Promise<void> {
  // Check if real inventory already imported
  try {
    const { rows: disabledRows } = await db.query<{ value: string }>("SELECT value FROM _meta WHERE key = 'disable_demo_seed'");
    if (!force && disabledRows.length > 0 && disabledRows[0].value === 'true') {
      return;
    }
    const { rows } = await db.query<{ value: string }>("SELECT value FROM _meta WHERE key = 'excel_inventory_imported'");
    if (!force && rows.length > 0 && rows[0].value === 'true') {
      return;
    }
  } catch (e) {
    // meta might not have the key yet
  }

  console.log('Populating complete real Excel inventory into database...');

  // Start Transaction
  await db.exec('BEGIN;');

  try {
    // 1. Delete initial placeholder or incomplete data
    await db.exec(`
      DELETE FROM sale_items;
      DELETE FROM sales;
      DELETE FROM purchase_items;
      DELETE FROM purchases;
      DELETE FROM verifications;
      DELETE FROM customers;
      DELETE FROM suppliers;
      DELETE FROM products;
    `);

    // 2. Insert Suppliers (chunks of 100)
    for (let i = 0; i < RAW_SUPPLIERS.length; i += 100) {
      const chunk = RAW_SUPPLIERS.slice(i, i + 100);
      const values = chunk.map(s => `(${sqlEscape(s.id)}, ${sqlEscape(s.name)}, ${sqlEscape(s.contact_person)}, ${sqlEscape(s.phone)}, ${sqlEscape(s.gstin)}, ${sqlEscape(s.address)}, ${sqlEscape(s.notes)})`).join(',\n');
      await db.exec(`INSERT INTO suppliers (id, name, contact_person, phone, gstin, address, notes) VALUES ${values} ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, phone = EXCLUDED.phone, address = EXCLUDED.address;`);
    }

    // 3. Insert Customers (chunks of 100)
    for (let i = 0; i < RAW_CUSTOMERS.length; i += 100) {
      const chunk = RAW_CUSTOMERS.slice(i, i + 100);
      const values = chunk.map(c => `(${sqlEscape(c.id)}, ${sqlEscape(c.name)}, ${sqlEscape(c.business_name)}, ${sqlEscape(c.phone)}, ${sqlEscape(c.gstin)}, ${sqlEscape(c.address)}, ${sqlEscape(c.notes)})`).join(',\n');
      await db.exec(`INSERT INTO customers (id, name, business_name, phone, gstin, address, notes) VALUES ${values} ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, phone = EXCLUDED.phone, address = EXCLUDED.address;`);
    }

    // 4. Insert Products (chunks of 100)
    for (let i = 0; i < RAW_PRODUCTS.length; i += 100) {
      const chunk = RAW_PRODUCTS.slice(i, i + 100);
      const values = chunk.map(p => `(${sqlEscape(p.id)}, ${sqlEscape(p.name)}, ${sqlEscape(p.category)}, ${sqlEscape(p.supplier)}, ${sqlEscape(p.rack_number)}, ${sqlEscape(p.size)}, ${p.cost}, ${p.price}, ${p.stock}, ${p.box_capacity}, ${p.reorder_level}, ${sqlEscape(p.box_status)}, ${sqlEscape(p.status)}, ${sqlEscape(p.notes)})`).join(',\n');
      await db.exec(`INSERT INTO products (id, name, category, supplier, rack_number, size, cost, price, stock, box_capacity, reorder_level, box_status, status, notes) VALUES ${values} ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, cost = EXCLUDED.cost, price = EXCLUDED.price, stock = EXCLUDED.stock, status = EXCLUDED.status, box_status = EXCLUDED.box_status, rack_number = EXCLUDED.rack_number;`);
    }

    // 5. Insert Purchases (chunks of 100)
    for (let i = 0; i < RAW_PURCHASES.length; i += 100) {
      const chunk = RAW_PURCHASES.slice(i, i + 100);
      const values = chunk.map(p => `(${sqlEscape(p.id)}, ${sqlEscape(p.po_number)}, ${sqlEscape(p.supplier)}, ${sqlEscape(p.supplier_invoice)}, ${sqlEscape(p.phone)}, ${sqlEscape(p.date)}, ${sqlEscape(p.expected_delivery)}, ${sqlEscape(p.received_date)}, ${p.item_count}, ${p.subtotal}, ${p.gst_rate}, ${p.gst_amount}, ${p.grand_total}, ${p.amount_paid}, ${sqlEscape(p.payment_status)}, ${sqlEscape(p.payment_method)}, ${sqlEscape(p.status)}, ${sqlEscape(p.notes)})`).join(',\n');
      await db.exec(`INSERT INTO purchases (id, po_number, supplier, supplier_invoice, phone, date, expected_delivery, received_date, item_count, subtotal, gst_rate, gst_amount, grand_total, amount_paid, payment_status, payment_method, status, notes) VALUES ${values} ON CONFLICT (id) DO NOTHING;`);
    }

    // 6. Insert Purchase Items (chunks of 200)
    for (let i = 0; i < RAW_PURCHASE_ITEMS.length; i += 200) {
      const chunk = RAW_PURCHASE_ITEMS.slice(i, i + 200);
      const values = chunk.map(item => `(${sqlEscape(item.purchase_id)}, ${sqlEscape(item.product_id)}, ${sqlEscape(item.name)}, ${item.cost}, ${item.qty}, ${item.gst_rate}, ${item.sort_order})`).join(',\n');
      await db.exec(`INSERT INTO purchase_items (purchase_id, product_id, name, cost, qty, gst_rate, sort_order) VALUES ${values};`);
    }

    // 7. Insert Sales (chunks of 100)
    for (let i = 0; i < RAW_SALES.length; i += 100) {
      const chunk = RAW_SALES.slice(i, i + 100);
      const values = chunk.map(s => `(${sqlEscape(s.id)}, ${sqlEscape(s.invoice)}, ${sqlEscape(s.customer)}, ${sqlEscape(s.phone)}, ${sqlEscape(s.date)}, ${s.item_count}, ${s.subtotal}, ${s.discount}, ${s.gst_rate}, ${s.gst_amount}, ${s.grand_total}, ${s.amount_paid}, ${sqlEscape(s.payment_method)}, ${sqlEscape(s.status)}, ${sqlEscape(s.channel)}, ${sqlEscape(s.notes)})`).join(',\n');
      await db.exec(`INSERT INTO sales (id, invoice, customer, phone, date, item_count, subtotal, discount, gst_rate, gst_amount, grand_total, amount_paid, payment_method, status, channel, notes) VALUES ${values} ON CONFLICT (id) DO NOTHING;`);
    }

    // 8. Insert Sale Items (chunks of 200)
    for (let i = 0; i < RAW_SALE_ITEMS.length; i += 200) {
      const chunk = RAW_SALE_ITEMS.slice(i, i + 200);
      const values = chunk.map(item => `(${sqlEscape(item.sale_id)}, ${sqlEscape(item.product_id)}, ${sqlEscape(item.name)}, ${item.price}, ${item.qty}, ${item.cost}, ${item.sort_order})`).join(',\n');
      await db.exec(`INSERT INTO sale_items (sale_id, product_id, name, price, qty, cost, sort_order) VALUES ${values};`);
    }

    // Set _meta flag
    await db.exec(`
      INSERT INTO _meta (key, value) VALUES ('excel_inventory_imported', 'true')
      ON CONFLICT (key) DO UPDATE SET value = 'true';
      INSERT INTO _meta (key, value) VALUES ('disable_demo_seed', 'false')
      ON CONFLICT (key) DO UPDATE SET value = 'false';
    `);

    await db.exec('COMMIT;');
    console.log('Successfully populated complete real Excel inventory into database!');
  } catch (err) {
    await db.exec('ROLLBACK;');
    console.error('Failed to populate real Excel inventory:', err);
    throw err;
  }
}
